def choose_move(observation):
    def clamp_step(v):
        return -1 if v < 0 else (1 if v > 0 else 0)

    def step_towards(ax, ay, bx, by):
        return [clamp_step(bx - ax), clamp_step(by - ay)]

    def dist2(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def first_pair(x):
        if isinstance(x, (list, tuple)) and len(x) >= 2:
            try:
                return [int(x[0]), int(x[1])]
            except:
                return None
        return None

    def extract_points(v):
        pts = []
        if not v:
            return pts
        if isinstance(v, dict):
            for key in ("positions", "cells", "items", "resources", "targets", "list"):
                if key in v:
                    pts.extend(extract_points(v.get(key)))
            if "x" in v and "y" in v:
                p = first_pair([v.get("x"), v.get("y")])
                if p is not None:
                    pts.append(p)
            return pts
        if isinstance(v, (list, tuple)):
            for item in v:
                if isinstance(item, dict):
                    p = None
                    for keys in (("x", "y"), ("row", "col"), ("i", "j")):
                        if keys[0] in item and keys[1] in item:
                            p = first_pair([item.get(keys[0]), item.get(keys[1])])
                            break
                    if p is None:
                        for k in ("position", "pos", "location", "cell"):
                            if k in item:
                                p = first_pair(item.get(k))
                                if p is not None:
                                    break
                    if p is not None:
                        pts.append(p)
                else:
                    p = first_pair(item)
                    if p is not None:
                        pts.append(p)
        return pts

    env = observation.get("environment_name", "resource_collection")
    self_pos = first_pair(observation.get("self_position")) or [0, 0]
    opp_pos = first_pair(observation.get("opponent_position")) or self_pos[:]

    w = observation.get("grid_width", 0) or observation.get("width", 0) or 0
    h = observation.get("grid_height", 0) or observation.get("height", 0) or 0

    role = observation.get("self_role", "")
    if env == "pursuit_evasion":
        if role == "pursuer":
            return step_towards(self_pos[0], self_pos[1], opp_pos[0], opp_pos[1])
        corners = []
        if w and h:
            corners = [[0, 0], [0, h - 1], [w - 1, 0], [w - 1, h - 1]]
        else:
            corners = [[-10, -10], [-10, 10], [10, -10], [10, 10]]
        target = max(corners, key=lambda p: dist2(p, opp_pos))
        return step_towards(self_pos[0], self_pos[1], target[0], target[1])

    if env == "territory_control":
        targets = []
        for key in ("unclaimed_cells", "opponent_territory", "neutral_cells", "frontier", "targets"):
            targets.extend(extract_points(observation.get(key)))
        if not targets:
            return step_towards(self_pos[0], self_pos[1], opp_pos[0], opp_pos[1])
        best = min(targets, key=lambda p: dist2(p, self_pos))
        return step_towards(self_pos[0], self_pos[1], best[0], best[1])

    resources = []
    for key in ("resources", "resource_positions", "resource_cells", "items", "targets"):
        resources.extend(extract_points(observation.get(key)))
    if resources:
        best = min(resources, key=lambda p: dist2(p, self_pos))
        return step_towards(self_pos[0], self_pos[1], best[0], best[1])

    # Fallback: move toward opponent unless fleeing seems safer on tiny maps.
    if w and h and abs(opp_pos[0] - self_pos[0]) + abs(opp_pos[1] - self_pos[1]) <= 2:
        away = [self_pos[0] - opp_pos[0], self_pos[1] - opp_pos[1]]
        return [clamp_step(away[0]), clamp_step(away[1])]
    return step_towards(self_pos[0], self_pos[1], opp_pos[0], opp_pos[1])

